import{_ as a,a as o}from"./chunks/ark_v6xrt_bottom.DSYH0zXV.js";import{_ as s,C as i,o as n,c as l,j as t,a as d,E as c,al as h}from"./chunks/framework.7vp1BMOE.js";const S=JSON.parse('{"title":"ARK Electronics ARKV6X-RT","description":"","frontmatter":{},"headers":[],"relativePath":"uk/flight_controller/ark_v6xrt.md","filePath":"uk/flight_controller/ark_v6xrt.md"}'),p={name:"uk/flight_controller/ark_v6xrt.md"};function u(g,e,m,f,b,_){const r=i("Badge");return n(),l("div",null,[e[0]||(e[0]=t("h1",{id:"ark-electronics-arkv6x-rt",tabindex:"-1"},[d("ARK Electronics ARKV6X-RT "),t("a",{class:"header-anchor",href:"#ark-electronics-arkv6x-rt","aria-label":'Permalink to "ARK Electronics ARKV6X-RT"'},"​")],-1)),c(r,{type:"tip",text:"main (PX4 v2.0)"}),e[1]||(e[1]=h('<div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>PX4 не розробляє цей (або будь-який інший) автопілот. Contact the <a href="https://arkelectron.com/contact-us/" target="_blank" rel="noreferrer">manufacturer</a> for hardware support or compliance issues.</p></div><p>The USA-built ARKV6X-RT flight controller is an NXP i.MX RT1176 variant of the <a href="./../flight_controller/ark_v6x">ARKV6X</a>, derived from the <a href="https://github.com/pixhawk/Pixhawk-Standards" target="_blank" rel="noreferrer">FMUv6X-RT and Pixhawk Autopilot Bus open source standards</a>.</p><p>Завдяки потрійній синхронізації IMU можливе узагальнення даних, голосування та фільтрація.</p><p><img src="'+a+'" alt="ARKV6X-RT Top"></p><p><img src="'+o+'" alt="ARKV6X-RT Bottom"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This flight controller is <a href="./../flight_controller/autopilot_manufacturer_supported">manufacturer supported</a>.</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>This flight controller is a module and requires a carrier board to work. The Pixhawk Autopilot Bus (PAB) form factor enables the ARKV6X-RT to be used on any <a href="./../flight_controller/pixhawk_autopilot_bus">PAB-compatible carrier board</a>, such as the <a href="./../flight_controller/ark_pab">ARK Pixhawk Autopilot Bus Carrier</a>. Which ports and outputs are physically broken out depends on the carrier.</p></div><h2 id="store" tabindex="-1">Where to Buy <a class="header-anchor" href="#store" aria-label="Permalink to &quot;Where to Buy {#store}&quot;">​</a></h2><p>Order from <a href="https://arkelectron.com/product/arkv6xrt" target="_blank" rel="noreferrer">ARK Electronics</a> (US).</p><h2 id="specifications" tabindex="-1">Specifications <a class="header-anchor" href="#specifications" aria-label="Permalink to &quot;Specifications {#specifications}&quot;">​</a></h2><ul><li><strong>Processor</strong><ul><li><strong>Main FMU processor:</strong> <a href="https://www.nxp.com/products/i.MX-RT1170" target="_blank" rel="noreferrer">NXP i.MX RT1176</a> (Arm® Cortex®-M7 at 996 MHz, 2 MB RAM). The second Cortex-M4 core is unused by PX4.</li><li><strong>Code store:</strong> no internal flash. Code executes in place from a 64 MB external octal NOR on FlexSPI1, of which PX4 uses the first 4 MB.</li><li><strong>IO processor:</strong> PX4IO v2, on carriers that fit one.</li></ul></li><li><strong>Sensors</strong><ul><li><strong>IMU:</strong> <a href="https://invensense.tdk.com/products/motion-tracking/6-axis/icm-45686/" target="_blank" rel="noreferrer">InvenSense ICM-45686</a> (SPI1), <a href="https://invensense.tdk.com/products/motion-tracking/6-axis/iim-20670/" target="_blank" rel="noreferrer">InvenSense IIM-20670</a> (SPI2), <a href="https://www.st.com/en/mems-and-sensors/lsm6dsv80x.html" target="_blank" rel="noreferrer">ST LSM6DSV80X</a> (SPI3)</li><li><strong>Barometer:</strong> <a href="https://www.bosch-sensortec.com/en/products/environmental-sensors/pressure-sensors/bmp390/" target="_blank" rel="noreferrer">Bosch BMP390</a> (I2C2)</li><li><strong>Magnetometer:</strong> <a href="https://www.st.com/en/mems-and-sensors/iis2mdc.html" target="_blank" rel="noreferrer">ST IIS2MDC</a> (I2C3)</li><li><strong>Heater:</strong> closed loop on the ICM-45686 die temperature</li></ul></li><li><strong>Interfaces</strong><ul><li><strong>PWM outputs:</strong> 12 FMU outputs, plus 8 more from PX4IO on carriers that fit one</li><li><strong>Serial ports:</strong> 8 (<code>GPS1</code>, <code>GPS2</code>, <code>TELEM1</code>, <code>TELEM2</code>, <code>TELEM3</code>, <code>TELEM4</code>, PX4IO/<code>RC</code>, Debug Console)</li><li><strong>I2C buses:</strong> 4 (I2C3 internal, the rest external)</li><li><strong>SPI buses:</strong> 4, of which SPI6 is external with 2 chip selects and 2 data-ready lines</li><li><strong>CAN buses:</strong> 2 enabled by default. PAB pins out a third; no ARK carrier breaks it out.</li><li><strong>Ethernet:</strong> 100BASE-T (ENET2)</li><li><strong>USB:</strong> Yes</li><li><strong>RC input:</strong> Yes</li><li><strong>Parameter storage:</strong> FRAM (FM25V02A) on FlexSPI2</li><li><strong>SD card:</strong> MicroSD slot</li></ul></li><li><strong>Electrical data</strong><ul><li><strong>Input voltage:</strong> 5 V</li><li><strong>Current draw:</strong> 500 mA (300 mA main system, 200 mA heater)</li><li><strong>Power monitoring:</strong> 2 digital power bricks, INA226 by default</li></ul></li><li><strong>Mechanical data</strong><ul><li><strong>Dimensions:</strong> 3.6 x 2.9 x 0.5 cm</li><li><strong>Weight:</strong> 5.0 g</li><li><strong>Form factor:</strong> <a href="https://github.com/pixhawk/Pixhawk-Standards/blob/master/DS-010%20Pixhawk%20Autopilot%20Bus%20Standard.pdf" target="_blank" rel="noreferrer">Pixhawk Autopilot Bus (PAB)</a></li></ul></li></ul><h2 id="imus" tabindex="-1">IMUs <a class="header-anchor" href="#imus" aria-label="Permalink to &quot;IMUs {#imus}&quot;">​</a></h2><p>Each IMU sits on its own SPI bus with an independent power rail and data-ready line:</p><table tabindex="0"><thead><tr><th>IMU</th><th>Шина</th><th>Full scale</th><th>Publish rate</th></tr></thead><tbody><tr><td>ICM-45686</td><td>SPI1</td><td>±32 g / ±4000 dps</td><td>800 Hz</td></tr><tr><td>IIM-20670</td><td>SPI2</td><td>±65.5 g / ±1966 dps</td><td>1000 Hz</td></tr><tr><td>LSM6DSV80X</td><td>SPI3</td><td>±16 g / ±4000 dps</td><td>768 Hz</td></tr></tbody></table><p>The ICM-45686 is the primary. The IIM-20670 is started last deliberately: its on-chip gyro low-pass cannot be set above 60 Hz, which is too much group delay for the rate loop, so it serves as a navigation and fallback IMU.</p><p>The LSM6DSV80X publishes its ±16 g accelerometer; the part&#39;s ±80 g high-g element is unused.</p><p><a href="./../advanced_config/parameter_reference#HEATER1_SENS_ID">HEATER1_SENS_ID</a> defaults to the ICM-45686. Run the <a href="./../config/accelerometer">accelerometer calibration</a> only after <code>heater status</code> reports the setpoint has been reached.</p><h2 id="схема-розташування-виводів" tabindex="-1">Схема розташування виводів <a class="header-anchor" href="#схема-розташування-виводів" aria-label="Permalink to &quot;Схема розташування виводів&quot;">​</a></h2><p>For the pinout of the ARKV6X-RT see the <a href="https://github.com/pixhawk/Pixhawk-Standards/blob/master/DS-010%20Pixhawk%20Autopilot%20Bus%20Standard.pdf" target="_blank" rel="noreferrer">DS-010 Pixhawk Autopilot Bus Standard</a>.</p><h2 id="налаштування-послідовного-порту" tabindex="-1">Налаштування послідовного порту <a class="header-anchor" href="#налаштування-послідовного-порту" aria-label="Permalink to &quot;Налаштування послідовного порту&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UART</th><th>Пристрій</th><th>Порт</th><th style="text-align:center;">Flow Control</th></tr></thead><tbody><tr><td>LPUART1</td><td>/dev/ttyS0</td><td><code>Debug Console</code></td><td style="text-align:center;">Ні</td></tr><tr><td>LPUART3</td><td>/dev/ttyS1</td><td><code>GPS1</code></td><td style="text-align:center;">Ні</td></tr><tr><td>LPUART4</td><td>/dev/ttyS2</td><td><code>TELEM1</code></td><td style="text-align:center;">Так</td></tr><tr><td>LPUART5</td><td>/dev/ttyS3</td><td><code>GPS2</code></td><td style="text-align:center;">Ні</td></tr><tr><td>LPUART6</td><td>/dev/ttyS4</td><td>PX4IO / <code>RC</code></td><td style="text-align:center;">Ні</td></tr><tr><td>LPUART8</td><td>/dev/ttyS5</td><td><code>TELEM2</code></td><td style="text-align:center;">Так</td></tr><tr><td>LPUART10</td><td>/dev/ttyS6</td><td><code>TELEM3</code></td><td style="text-align:center;">Так</td></tr><tr><td>LPUART11</td><td>/dev/ttyS7</td><td><code>TELEM4</code></td><td style="text-align:center;">Ні</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The mapping above applies to the running PX4 firmware. The ARKV6X-RT bootloader enables only <code>LPUART8</code> (<code>TELEM2</code>), so when flashing firmware over UART with <a href="https://github.com/PX4/PX4-Autopilot/blob/main/Tools/px4_uploader.py" target="_blank" rel="noreferrer"><code>px4_uploader.py</code></a> you must connect to the <code>TELEM2</code> port — no other UART will respond in bootloader mode.</p></div><h2 id="pwm_outputs" tabindex="-1">PWM Outputs <a class="header-anchor" href="#pwm_outputs" aria-label="Permalink to &quot;PWM Outputs {#pwm_outputs}&quot;">​</a></h2><p>The module provides 12 FMU PWM outputs, and 8 more from PX4IO on carriers that fit one. How many reach a connector depends on the carrier board.</p><p>FMU outputs 1-8 support <a href="./../peripherals/dshot">DShot</a> and <a href="./../peripherals/dshot#bidirectional-dshot-telemetry">Bidirectional DShot</a>; outputs 9-12 are PWM only.</p><p>Each FMU output has its own FlexPWM submodule, so unlike an STM32 target there are no output groups: protocol and rate can be set per output.</p><h2 id="radio_control" tabindex="-1">Radio Control <a class="header-anchor" href="#radio_control" aria-label="Permalink to &quot;Radio Control {#radio_control}&quot;">​</a></h2><p>Для того щоб керувати транспортним засобом <em>вручну</em>, потрібна система радіоуправління (RC) (PX4 не потребує системи радіоуправління для автономних режимів польоту).</p><p>Вам потрібно <a href="./../getting_started/rc_transmitter_receiver">вибрати сумісний передавач/приймач</a> і <em>зв&#39;язати</em> їх таким чином, щоб вони взаємодіяли (ознайомтеся з інструкціями, що додаються до вашого конкретного передавача/приймача).</p><p>RC shares LPUART6 with PX4IO. On a carrier fitted with PX4IO, the IO processor decodes SBUS, PPM, and DSM/DSMX. CRSF is decoded on the FMU instead and is enabled by default (<a href="./../advanced_config/parameter_reference#RC_CRSF_PRT_CFG">RC_CRSF_PRT_CFG</a> is set to the <code>RC</code> port); <a href="./../advanced_config/parameter_reference#RC_SBUS_PRT_CFG">RC_SBUS_PRT_CFG</a> is off so that the FMU driver does not contend with PX4IO.</p><h2 id="gps_compass" tabindex="-1">GPS &amp; Compass <a class="header-anchor" href="#gps_compass" aria-label="Permalink to &quot;GPS &amp; Compass {#gps_compass}&quot;">​</a></h2><p>PX4 supports GPS modules connected to the GPS ports listed below. The module should be <a href="./../assembly/mount_gps_compass">mounted on the frame</a> as far away from other electronics as possible, with the direction marker pointing towards the front of the vehicle.</p><p>The GPS ports are:</p><ul><li><code>GPS1</code> (LPUART3): safety switch, buzzer, LED, and compass I2C on a PAB carrier</li><li><code>GPS2</code> (LPUART5): basic GPS port</li></ul><p>The onboard IIS2MDC is on an internal bus and is intended as a backup. An external compass in a GPS/compass module is normally used for yaw.</p><h2 id="power" tabindex="-1">Power <a class="header-anchor" href="#power" aria-label="Permalink to &quot;Power {#power}&quot;">​</a></h2><p>The module is powered from the carrier board over the PAB connector, so the power connector type and its ratings are properties of the carrier. The voltage the module itself accepts is under <a href="#specifications">Specifications</a>.</p><p>Two digital power bricks are supported. <a href="./../advanced_config/parameter_reference#SENS_EN_INA226">SENS_EN_INA226</a> is enabled by default; the INA228 and INA238 drivers are also built in for carriers that fit those parts. An ADS1115 external ADC can be enabled with <a href="./../advanced_config/parameter_reference#ADC_ADS1115_EN">ADC_ADS1115_EN</a> for analog monitoring instead.</p><p>For battery and power module configuration see <a href="./../config/battery">Battery and Power Module Setup</a>.</p><h2 id="debug_port" tabindex="-1">Debug Port <a class="header-anchor" href="#debug_port" aria-label="Permalink to &quot;Debug Port {#debug_port}&quot;">​</a></h2><p>The <a href="./../debug/system_console">PX4 System Console</a> runs on LPUART1, and the <a href="./../debug/swd_debug">SWD interface</a> is brought out alongside it, both on the carrier&#39;s FMU Debug connector.</p><h2 id="збірка-прошивки" tabindex="-1">Збірка прошивки <a class="header-anchor" href="#збірка-прошивки" aria-label="Permalink to &quot;Збірка прошивки&quot;">​</a></h2><p>To <a href="./../dev_setup/building_px4">build PX4</a> for this target:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ark_fmu-v6xrt_default</span></span></code></pre></div><p>Uploading over USB works as it does on any other board once a bootloader is present:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ark_fmu-v6xrt_default</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upload</span></span></code></pre></div><p>A board with no bootloader — or a wiped NOR — has to be recovered over SWD. Because the RT1176 has no internal flash, this needs NXP&#39;s device family pack for the flash algorithm and a FlexSPI preconditioning step; see the <a href="https://github.com/PX4/PX4-Autopilot/blob/main/boards/ark/fmu-v6xrt/README.md" target="_blank" rel="noreferrer">board README</a> for the procedure.</p><h2 id="дивіться-також" tabindex="-1">Дивіться також <a class="header-anchor" href="#дивіться-також" aria-label="Permalink to &quot;Дивіться також&quot;">​</a></h2><ul><li><a href="./../flight_controller/ark_v6x">ARK Electronics ARKV6X</a></li><li><a href="./../flight_controller/ark_pab">ARK Electronics Pixhawk Autopilot Bus Carrier</a></li></ul>',49))])}const A=s(p,[["render",u]]);export{S as __pageData,A as default};
